/**
 * Returns a consistent daily quote based on the current day of the year.
 */
export function getDailyQuote(now = new Date()): MotivationalQuote {
  const startOfYear = new Date(now.getFullYear(), 0, 0);
  const diff = now.getTime() - startOfYear.getTime();
  const dayOfYear = Math.floor(diff / (1000 * 60 * 60 * 24));
  const index = Math.abs(dayOfYear) % MOTIVATIONAL_QUOTES.length;
  return MOTIVATIONAL_QUOTES[index];
}

/**
 * Returns a randomly picked quote from the pool, optionally avoiding the current quote id.
 * Employs an O(1) constant-time selection algorithm without array allocations to protect 60-120fps interactions.
 */
export function getRandomQuote(excludeId?: number): MotivationalQuote {
  const total = MOTIVATIONAL_QUOTES.length;
  if (total === 0) {
    return { id: 0, quote: "", author: "", category: "finance" };
  }
  if (total === 1) {
    return MOTIVATIONAL_QUOTES[0];
  }

  let randomIndex = Math.floor(Math.random() * total);
  if (excludeId !== undefined && MOTIVATIONAL_QUOTES[randomIndex]?.id === excludeId) {
    randomIndex = (randomIndex + 1 + Math.floor(Math.random() * (total - 1))) % total;
  }
  return MOTIVATIONAL_QUOTES[randomIndex] ?? MOTIVATIONAL_QUOTES[0];
}
